#!/usr/bin/env bash
# HDB-37 stage 2: materialize an SPB closure and measure what it costs.
#
# Reads the Creative Works generated by an earlier stage (default: the
# calibration set) plus the SPB ontologies, runs the OWL 2 RL closure, then
# serves the result so both the materialize peak and the serving footprint are
# measured — the two numbers that decide whether a given datasetSize fits in
# hornbench's 124 GiB.
#
# hornbench has no /usr/bin/time, so peak RSS comes from polling VmHWM.
#
# Knobs: GEN_DIR (Creative Works to close over), CLOSURE (output path),
#        WITH_REFDATA=1 to include the 24M-triple reference datasets.
set -uo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
OUT="$PWD/bench-out"; mkdir -p "$OUT"
SUM="$OUT/SUMMARY.md"

DIST="${SPB_ASSETS:-/home/bench/src/horndb/crates/harness/data/ldbc-spb/dist}"
WORK="${SPB_WORK:-/home/bench/horndb-bench/spb-sf256}"
GEN_DIR="${GEN_DIR:-$WORK/generated-cal}"
CLOSURE="${CLOSURE:-$WORK/closure-cal.nt}"
BIND="${HORNDB_BIND:-127.0.0.1:3842}"
WITH_REFDATA="${WITH_REFDATA:-0}"

{ echo "# HDB-37 stage 2 — materialize + serve an SPB closure"
  echo; echo "Host \`$(hostname)\` · $(date -Is) · commit \`$(git rev-parse --short HEAD)\`"
  echo; echo "GEN_DIR=\`$GEN_DIR\` CLOSURE=\`$CLOSURE\` WITH_REFDATA=$WITH_REFDATA"; } > "$SUM"
sec() { { echo; echo "## $*"; echo '```'; } >> "$SUM"; }
end() { echo '```' >> "$SUM"; }

# Run "$@" and print its peak RSS (KiB) by polling VmHWM. Sets PEAK_KB / RC.
run_peak() {
  local log="$1"; shift
  "$@" > "$log" 2>&1 &
  local pid=$! hwm=0 cur
  while kill -0 $pid 2>/dev/null; do
    cur=$(awk '/VmHWM/{print $2}' /proc/$pid/status 2>/dev/null)
    [ -n "${cur:-}" ] && [ "$cur" -gt "$hwm" ] && hwm=$cur
    sleep 2
  done
  wait $pid; RC=$?; PEAK_KB=$hwm
}

sec "inputs"
mapfile -t ONTO < <(find "$DIST/data/ontologies" -name '*.ttl' -not -path '*/ldbc/*' | sort)
mapfile -t CWS  < <(ls "$GEN_DIR"/generatedCreativeWorks-*.nt 2>/dev/null)
INPUTS=("${ONTO[@]}" "${CWS[@]}")
if [ "$WITH_REFDATA" = 1 ]; then
  mapfile -t REFDATA < <(find "$DIST/data/datasets" -type f \( -name '*.ttl' -o -name '*.nt' \) | sort)
  INPUTS+=("${REFDATA[@]}")
fi
GEN_TRIPLES=$(cat "$GEN_DIR"/generatedCreativeWorks-*.nt 2>/dev/null | wc -l)
{ echo "ontology files: ${#ONTO[@]}"
  echo "creative-work files: ${#CWS[@]}  (${GEN_TRIPLES} triples)"
  echo "total input files: ${#INPUTS[@]}"
  free -h; df -h / | tail -1; } >> "$SUM"
end
[ "$GEN_TRIPLES" -lt 1000 ] && { echo "ABORT: no generated Creative Works under $GEN_DIR" >> "$SUM"; exit 1; }

sec "build"
cargo build --release -p horndb-sparql --bin serve --features server >> "$SUM" 2>&1 || { echo BUILD-FAIL >> "$SUM"; end; exit 1; }
cargo build --release -p horndb-bench-rdfox >> "$SUM" 2>&1 || { echo BUILD-FAIL >> "$SUM"; end; exit 1; }
echo ok >> "$SUM"
end

sec "materialize"
t0=$(date +%s)
run_peak "$OUT/materialize.log" ./target/release/horndb-bench materialize --dump-nt "$CLOSURE" --data "${INPUTS[@]}"
t1=$(date +%s); MAT_S=$((t1-t0)); MAT_RC=$RC; MAT_PEAK=$PEAK_KB
tail -20 "$OUT/materialize.log" >> "$SUM"
CLO_TRIPLES=$(wc -l < "$CLOSURE" 2>/dev/null || echo 0)
CLO_BYTES=$(stat -c %s "$CLOSURE" 2>/dev/null || echo 0)
{ echo "--- exit=$MAT_RC wall=${MAT_S}s peakRSS=$((MAT_PEAK/1024))MiB ---"
  echo "closure: $CLO_TRIPLES triples, $CLO_BYTES bytes"; } >> "$SUM"
end
[ "$CLO_TRIPLES" -lt 1000 ] && { echo "ABORT: materialize produced no closure" >> "$SUM"; exit 1; }

sec "serve the closure"
t0=$(date +%s)
./target/release/serve --bind "$BIND" --data "$CLOSURE" > "$OUT/serve-closure.log" 2>&1 &
SPID=$!; ready=0; SHWM=0
for i in $(seq 1 3600); do
  cur=$(awk '/VmHWM/{print $2}' /proc/$SPID/status 2>/dev/null)
  [ -n "${cur:-}" ] && [ "$cur" -gt "$SHWM" ] && SHWM=$cur
  curl -fsS "http://$BIND/readyz" >/dev/null 2>&1 && { ready=1; break; }
  kill -0 $SPID 2>/dev/null || break
  sleep 1
done
t1=$(date +%s); LOAD_S=$((t1-t0))
SRSS=$(awk '/VmRSS/{print $2}' /proc/$SPID/status 2>/dev/null || echo 0)
{ echo "ready=$ready after ${LOAD_S}s"
  echo "serve peak VmHWM: $((SHWM/1024)) MiB   steady VmRSS: $((SRSS/1024)) MiB"; } >> "$SUM"
curl -sS -G --data-urlencode 'query=SELECT (COUNT(*) AS ?n) WHERE {?s ?p ?o}' \
     -H 'Accept: text/csv' "http://$BIND/query" >> "$SUM" 2>&1
tail -5 "$OUT/serve-closure.log" >> "$SUM"
kill $SPID 2>/dev/null; wait $SPID 2>/dev/null
end

{
  echo
  echo "## Per-triple costs and the scale that fits"
  echo
  awk -v gt="$GEN_TRIPLES" -v ct="$CLO_TRIPLES" -v cb="$CLO_BYTES" -v ms="$MAT_S" \
      -v mp="$MAT_PEAK" -v sh="$SHWM" -v ls="$LOAD_S" 'BEGIN{
    printf "| quantity | value |\n|---|---|\n";
    printf "| generated (asserted CW) triples | %d |\n", gt;
    printf "| closure triples | %d |\n", ct;
    if (gt>0) printf "| closure expansion | %.2fx |\n", ct/gt;
    printf "| closure .nt bytes/triple | %.1f |\n", (ct>0? cb/ct : 0);
    printf "| materialize wall-clock | %d s (%.0f k asserted triples/s) |\n", ms, (ms>0? gt/ms/1000 : 0);
    printf "| materialize peak RSS | %.2f GiB (%.0f B per asserted triple) |\n", mp/1048576, (gt>0? mp*1024/gt : 0);
    printf "| serve load wall-clock | %d s |\n", ls;
    printf "| serve peak RSS | %.2f GiB (%.0f B per closure triple) |\n", sh/1048576, (ct>0? sh*1024/ct : 0);
    print "";
    print "Largest datasetSize that fits, by constraint (124 GiB RAM, keep ~15% headroom => 105 GiB budget):";
    print "";
    printf "| constraint | max datasetSize |\n|---|---|\n";
    if (gt>0 && mp>0) printf "| materialize peak RSS <= 105 GiB | %.0f |\n", 105*1073741824/(mp*1024/gt);
    if (gt>0 && sh>0 && ct>0) printf "| serve peak RSS <= 105 GiB | %.0f |\n", 105*1073741824/(sh*1024/ct*(ct/gt));
    print "";
    printf "Projected at the SF=0.256 target (datasetSize=256000000, x%.1f):\n", 256000000/gt;
    printf "  closure %.0f M triples, .nt %.0f GiB, materialize %.1f h peak %.0f GiB, serve peak %.0f GiB\n",
      ct*(256000000/gt)/1e6, cb*(256000000/gt)/1073741824, ms*(256000000/gt)/3600,
      mp*1024*(256000000/gt)/gt/1073741824, sh*1024*(256000000/gt)/gt/1073741824;
  }'
  echo; echo '```'; free -h; df -h / | tail -1; echo '```'
} >> "$SUM"
